from modele import *
from donnees_figures import triangle,schema

def R(i,t,e,c,m,k,values=('','','')):
    return E(t,e,c,m,k,figure=triangle(f'trigo-{i:02}',valeurs=values))

chapitre(14,'trigonometrie','Trigonométrie du triangle rectangle','4 · Espace et géométrie',
'Cosinus · Sinus · Tangente · Longueurs · Angles',
['Choisir le rapport adapté à l’angle et aux données.','Calculer une longueur ou un angle aigu.','Démontrer et utiliser $(\\cos\\widehat B)^2+(\\sin\\widehat B)^2=1$.'],['Pythagore, Thalès et proportionnalité.'],[
r'''\essSection{1}{Trois rapports pour un angle aigu}
\begin{definition}Dans ABC rectangle en A, pour l’angle $\widehat B$, BC est l’hypoténuse, AB le côté adjacent et AC le côté opposé. Les deux derniers rôles s’échangent si l’on choisit l’angle $\widehat C$.\end{definition}
\begin{propriete}$\cos\widehat B=\dfrac{AB}{BC}$, $\sin\widehat B=\dfrac{AC}{BC}$ et $\tan\widehat B=\dfrac{AC}{AB}$. Ces rapports ne dépendent que de l’angle : deux triangles rectangles ayant le même angle aigu peuvent être placés l’un dans l’autre, et le théorème de Thalès donne les mêmes rapports.\end{propriete}
\begin{savoirfaire}[Trouver une longueur]Écrire le rapport avec les noms des côtés avant de remplacer. Si BC = 10 cm et $\widehat B=35^\circ$, $AC=10\sin35^\circ\approx5{,}74$ cm. Si AB = 10 cm, on utiliserait $AC=10\tan35^\circ$.\end{savoirfaire}
\begin{propriete}Pour tout angle aigu, $(\cos\widehat B)^2+(\sin\widehat B)^2=1$. En effet, la somme vaut $\dfrac{AB^2+AC^2}{BC^2}$, et $AB^2+AC^2=BC^2$ d’après Pythagore.\end{propriete}
\begin{attention}La calculatrice doit être en mode degrés. Un sinus ou cosinus d’angle aigu est entre 0 et 1 ; une hypoténuse reste le plus long côté.\end{attention}''',
r'''\essSection{2}{Angles et problèmes}
\begin{savoirfaire}[Trouver un angle]Si AB = 6 cm et BC = 10 cm, $\cos\widehat B=0{,}6$. Utiliser la fonction inverse du cosinus, souvent notée $\cos^{-1}$ ou acos : $\widehat B\approx53{,}1^\circ$. Cette touche ne calcule pas $1/\cos$.\end{savoirfaire}
\begin{propriete}Les deux angles aigus d’un triangle rectangle ont pour somme $90^\circ$. Cette relation fournit un contrôle ou un autre moyen de calcul.\end{propriete}
\begin{savoirfaire}[Une mesure indirecte]Pour une hauteur inaccessible, dessiner l’horizontale au niveau de l’observateur et sa ligne de visée. La hauteur calculée par tangente est celle au-dessus de cette horizontale ; ajouter ensuite la hauteur de l’instrument si nécessaire.\end{savoirfaire}
\begin{attention}Conserver les valeurs de calculatrice non arrondies jusqu’à la dernière étape. Préciser l’unité et la précision demandée. Un angle observé et une distance mesurés restent des données de modèle, avec une précision limitée.\end{attention}'''],[
R(1,'Nommer les côtés',r"ABC est rectangle en A. Pour l’angle $\widehat B$, identifier le côté opposé, l’adjacent et l’hypoténuse.",r"Le côté opposé est $\res{AC}$, l’adjacent est $\res{AB}$ et l’hypoténuse est $\res{BC}$. AB touche B mais n’est pas l’hypoténuse.","Commencer par l’hypoténuse.","assert {'AC','AB','BC'}==set(['AC','AB','BC'])"),
R(2,'Choisir le cosinus',r"ABC est rectangle en A. AB = 6 cm et BC = 10 cm. Donner $\cos\widehat B$.",r"$\cos\widehat B=AB/BC=6/10=\res{0{,}6}$. Le rapport utilise l’adjacent et l’hypoténuse.","Écrire les noms des côtés avant les nombres.","assert Rational(6,10)==Rational('.6')",('6 cm','','10 cm')),
R(3,'Choisir le sinus',r"ABC est rectangle en A. AC = 8 cm et BC = 10 cm. Donner $\sin\widehat B$.",r"$\sin\widehat B=AC/BC=8/10=\res{0{,}8}$. AC est opposé à $\widehat B$.","Repérer le côté qui ne touche pas l’angle B.","assert Rational(8,10)==Rational('.8')",('','8 cm','10 cm')),
R(4,'Choisir la tangente',r"ABC est rectangle en A. AB = 6 cm et AC = 8 cm. Donner $\tan\widehat B$.",r"$\tan\widehat B=AC/AB=8/6=\res{4/3}$. Une tangente peut dépasser 1, contrairement au sinus ou au cosinus d’un angle aigu.","La tangente ne fait pas intervenir l’hypoténuse.","assert Rational(8,6)==Rational(4,3)",('6 cm','8 cm','')),
R(5,'Une première longueur',r"ABC est rectangle en A, $\widehat B=30^\circ$ et BC = 12 cm. Calculer AC.",r"$AC=BC\sin30^\circ=12\times0{,}5=\res{6\text{ cm}}$. Le côté opposé est la moitié de l’hypoténuse pour cet angle.","Isoler la longueur dans le rapport.","assert 12*sin(pi/6)==6",('','','12 cm')),
R(6,'Un côté adjacent',r"ABC est rectangle en A. $\widehat B=40^\circ$ et BC = 9 cm. Calculer AB au millimètre.",r"$AB=9\cos40^\circ\approx6{,}8944$ cm, donc $\res{AB\approx6{,}9\text{ cm}}$ au millimètre. Le millimètre représente 0,1 cm.","Relier la précision à l’unité de travail.","assert round(9*math.cos(math.radians(40)),1)==6.9",('?','','9 cm')),
R(7,'Une hypoténuse',r"ABC est rectangle en A. $\widehat B=50^\circ$ et AB = 7 cm. Calculer BC au dixième de centimètre.",r"$\cos50^\circ=7/BC$, donc $BC=7/\cos50^\circ\approx\res{10{,}9\text{ cm}}$. Multiplier par le cosinus aurait donné un côté trop court.","Résoudre l’égalité avant de calculer.","assert round(7/math.cos(math.radians(50)),1)==10.9",('7 cm','','?')),
R(8,'Un angle par cosinus',r"ABC est rectangle en A, AB = 6 cm et BC = 10 cm. Calculer $\widehat B$ au degré.",r"$\cos\widehat B=0{,}6$. La fonction inverse donne $\widehat B\approx53{,}13^\circ$, donc $\res{\widehat B\approx53^\circ}$. L’angle $\widehat C$ vaut alors environ 37 degrés.","Utiliser la fonction inverse en mode degrés.","assert round(math.degrees(math.acos(.6)))==53",('6 cm','','10 cm')),
R(9,'Un angle par tangente',r"ABC est rectangle en A, AC = 5 cm et AB = 12 cm. Calculer $\widehat B$ au dixième de degré.",r"$\tan\widehat B=5/12$, donc $\widehat B\approx\res{22{,}6^\circ}$. L’opposé est inférieur à l’adjacent : un angle inférieur à 45 degrés est cohérent.","Choisir le rapport contenant les deux données.","assert round(math.degrees(math.atan(5/12)),1)==22.6",('12 cm','5 cm','')),
R(10,'Cosinus et sinus liés',r"ABC est rectangle en A. Démontrer que $(\cos\widehat B)^2+(\sin\widehat B)^2=1$. Sachant que $\cos\widehat B=0{,}6$, en déduire $\sin\widehat B$.",r"$(\cos\widehat B)^2+(\sin\widehat B)^2=\dfrac{AB^2}{BC^2}+\dfrac{AC^2}{BC^2}=\dfrac{AB^2+AC^2}{BC^2}=1$ d’après Pythagore. Ensuite $(\sin\widehat B)^2=1-0{,}36=0{,}64$ ; un sinus d’angle aigu est positif, donc $\res{\sin\widehat B=0{,}8}$.","Écrire les rapports, puis utiliser l’égalité de Pythagore.","a,b,c=symbols('a b c',positive=True); assert simplify((a/c)**2+(b/c)**2-1).subs(c,sqrt(a**2+b**2))==0 and sqrt(1-Rational(36,100))==Rational(4,5)"),
E('La hauteur d’un bâtiment',r"Un appareil à 1,6 m du sol vise le sommet d’un bâtiment avec un angle d’élévation de 32 degrés. Il est à 25 m horizontalement du pied. Le sol est horizontal. Calculer la hauteur au décimètre.",r"Au-dessus de l’appareil, la hauteur vaut $25\tan32^\circ\approx15{,}6217$ m. En ajoutant 1,6 m, la hauteur totale est $\res{17{,}2\text{ m}}$ au décimètre. Oublier la hauteur de visée sous-estimerait le résultat.","Séparer hauteur au-dessus de la visée et hauteur totale.","assert round(25*math.tan(math.radians(32))+1.6,1)==17.2",figure='trigo-batiment'),
R(12,'Une rampe et son angle',r"Une rampe monte de 0,8 m pour 10 m d’avancée horizontale. Dans ABC, A est l’angle droit, AB l’avancée et AC la hauteur. Calculer $\widehat B$ au dixième et la pente définie par $100\,AC/AB$.",r"$\widehat B=\tan^{-1}(0{,}8/10)\approx\res{4{,}6^\circ}$. La pente est $\res{8\,\%}$. 8 \% ne signifie donc pas un angle de 8 degrés.","Distinguer pourcentage de pente et mesure angulaire.","assert round(math.degrees(math.atan(.08)),1)==4.6 and Rational('.8')/10*100==8",('10 m','0,8 m','')),
R(13,'Un câble',r"Un câble BC de 18 m fait un angle $\widehat B$ de 65 degrés avec le sol horizontal AB. AC est vertical. Calculer la hauteur AC et la distance AB au dixième de mètre.",r"$AC=18\sin65^\circ\approx\res{16{,}3\text{ m}}$ et $AB=18\cos65^\circ\approx\res{7{,}6\text{ m}}$. Les calculs non arrondis vérifient Pythagore.","Calculer les deux projections de l’hypoténuse.","assert round(18*math.sin(math.radians(65)),1)==16.3 and round(18*math.cos(math.radians(65)),1)==7.6",('?','?','18 m')),
E('Un toit symétrique',r"Le toit a pour section un triangle isocèle de base 8 m ; chaque versant fait 35 degrés avec l’horizontale. Calculer sa hauteur puis la longueur d’un versant au centimètre.",r"La hauteur partage la base en deux segments de 4 m. Elle vaut $4\tan35^\circ\approx\res{2{,}80\text{ m}}$. Un versant mesure $4/\cos35^\circ\approx\res{4{,}88\text{ m}}$. On utilise 4 m, pas la base entière.","Exploiter la symétrie pour obtenir un triangle rectangle.","assert round(4*math.tan(math.radians(35)),2)==2.80 and round(4/math.cos(math.radians(35)),2)==4.88",figure='trigo-toit'),
R(15,'Diagnostiquer une erreur',r"ABC est rectangle en A. $\widehat B=38^\circ$, AB = 7 cm. Un élève annonce AC = $7\sin38^\circ$. Corriger puis donner AC au dixième.",r"AB est adjacent et AC opposé à $\widehat B$ ; leur rapport est la tangente. $\tan38^\circ=AC/7$, donc $\res{AC=7\tan38^\circ\approx5{,}5\text{ cm}}$. Le sinus exigerait l’hypoténuse au dénominateur.","Contrôler les côtés du rapport, pas seulement le résultat.","assert round(7*math.tan(math.radians(38)),1)==5.5",('7 cm','?',''))
],reperes=['Choisir cosinus, sinus ou tangente','Calculer une longueur','Calculer un angle aigu','Relation $\\cos^2+\\sin^2=1$ et mesures indirectes'],deco='geometrie')

def W(i,t,e,c,m,k,fig=None):
    return E(t,e,c,m,k,figure=fig or f'vect-{i:02}')

chapitre(15,'vecteurs','Translations et vecteurs','4 · Espace et géométrie',
'Symétries · Translations · Vecteurs égaux · Somme · Relation de Chasles',
['Construire l’image d’une figure par symétrie, demi-tour ou translation.','Reconnaître des vecteurs égaux et un parallélogramme.','Construire une somme de vecteurs et utiliser la relation de Chasles.'],['Symétrie axiale, demi-tour, translation et parallélogrammes.'],[
r'''\essSection{1}{Translations et vecteurs}
\begin{definition}La translation qui transforme A en B transforme tout point C en l’unique point D tel que ABDC soit un parallélogramme, éventuellement aplati. On l’appelle la translation de vecteur $\vect{AB}$.\end{definition}
\begin{definition}Pour deux points distincts A et B, le vecteur $\vect{AB}$ est défini par la direction de la droite (AB), le sens de A vers B et la longueur AB, appelée norme. On le représente par une flèche ; deux vecteurs sont égaux s’ils ont même direction, même sens et même longueur.\end{definition}
\begin{propriete}$\vect{AB}=\vect{CD}$ si et seulement si ABDC est un parallélogramme, éventuellement aplati. Deux vecteurs égaux définissent la même translation.\end{propriete}
\begin{definition}Le vecteur nul est $\vect{AA}=\vect{BB}=\vec0$ : la translation correspondante ne déplace aucun point. L’opposé de $\vect{AB}$ est $-\vect{AB}=\vect{BA}$, de même direction et même longueur, mais de sens contraire.\end{definition}
\begin{attention}L’ordre des lettres compte : $\vect{AB}=\vect{DC}$ signifie que ABCD est un parallélogramme, alors que $\vect{AB}=\vect{CD}$ correspond à ABDC. Symétries, demi-tours et translations conservent longueurs, angles, alignements et aires.\end{attention}''',
r'''\essSection{2}{Somme de vecteurs et relation de Chasles}
\begin{propriete}Enchaîner la translation de vecteur $\vect{AB}$ puis celle de vecteur $\vect{BC}$ revient à appliquer la translation de vecteur $\vect{AC}$. On définit ainsi la somme :
\[\vect{AB}+\vect{BC}=\vect{AC}\qquad\text{(relation de Chasles).}\]
En particulier $\vect{AB}+\vect{BA}=\vect{AA}=\vec0$.\end{propriete}
\begin{savoirfaire}[Construire $\vec u+\vec v$]À partir d’un point O, tracer un représentant $\vect{OP}$ de $\vec u$, puis, à partir de P, un représentant $\vect{PS}$ de $\vec v$. Alors $\vec u+\vec v=\vect{OS}$. On note $2\vect{AB}$ la somme $\vect{AB}+\vect{AB}$ : même direction, même sens, longueur double.\end{savoirfaire}
\begin{propriete}[Règle du parallélogramme]Si ABCD est un parallélogramme, alors $\vect{AB}+\vect{AD}=\vect{AC}$ : on remplace $\vect{AD}$ par le vecteur égal $\vect{BC}$, puis on applique Chasles.\end{propriete}
\begin{attention}La somme de deux vecteurs n’est pas la somme de leurs longueurs : $AB+BC$ n’est égal à $AC$ que si B appartient au segment [AC].\end{attention}'''],[
W(1,'Symétrie et demi-tour',r"Sur le quadrillage, construire l’image A’B’C’ du triangle ABC par la symétrie d’axe (d), puis son image A’’B’’C’’ par le demi-tour de centre O. Ces transformations conservent-elles les longueurs ?",r"Par la symétrie, chaque point est reporté perpendiculairement à (d), de l’autre côté et à la même distance : A et C sont à 6 carreaux de (d), B à 3 carreaux ; on obtient $\res{A'B'C'}$, tracé en vert. Par le demi-tour, O est le milieu de chaque segment point-image : on reproduit au-delà de O le déplacement de A vers O, soit 4 carreaux à droite et 3 en haut, pour placer A’’ ; de même pour $\res{B''\text{ et }C''}$. Les deux transformations $\res{\text{conservent les longueurs}}$.","Reporter les distances sur le quadrillage, point par point.","A=(1,1);B=(4,1);C=(1,3);O=(5,4)\nsym=lambda P:(14-P[0],P[1])\ndt=lambda P:(2*O[0]-P[0],2*O[1]-P[1])\nassert [sym(P) for P in (A,B,C)]==[point('vect-01',p) for p in (\"A'\",\"B'\",\"C'\")]==[(13,1),(10,1),(13,3)] and [dt(P) for P in (A,B,C)]==[(9,7),(6,7),(9,5)]"),
W(2,'Caractériser un vecteur',r"Le côté d’un carreau représente 1 cm. Décrire le vecteur $\vect{AB}$ : direction, sens et longueur. Construire ensuite le point D tel que $\vect{CD}=\vect{AB}$.",r"La direction est celle de la droite (AB), le sens va de A vers B. Le déplacement est de 4 carreaux vers la droite et 3 vers le haut : $AB=\sqrt{4^2+3^2}=\res{5\text{ cm}}$. On applique le même déplacement à partir de C : D est 4 carreaux à droite et 3 au-dessus de C.","Lire le déplacement horizontal et vertical, puis le reproduire.","assert vecteur('vect-02','A','B')==vecteur('vect-02','C','D')==(4,3) and 4**2+3**2==25"),
W(3,'Des vecteurs égaux',r"Parmi les vecteurs $\vect{CD}$, $\vect{EF}$, $\vect{GH}$ et $\vect{IJ}$ dessinés, lesquels sont égaux à $\vect{AB}$ ? Lequel est son opposé ?",r"$\vect{CD}$ et $\vect{IJ}$ correspondent au même déplacement que $\vect{AB}$ (2 à droite, 1 en haut) : $\res{\vect{CD}=\vect{IJ}=\vect{AB}}$. $\vect{EF}$ a même direction et même longueur, mais un sens contraire : $\res{\vect{EF}=-\vect{AB}=\vect{BA}}$. $\vect{GH}$ n’a pas la même direction.","Comparer direction, sens et longueur, ou le déplacement sur le quadrillage.","v=lambda p,q:vecteur('vect-03',p,q)\nassert v('A','B')==v('C','D')==v('I','J')==(2,1) and v('E','F')==(-2,-1) and v('G','H')==(2,2)"),
W(4,'Image par une translation',r"Construire l’image D du point C par la translation de vecteur $\vect{AB}$. Quelle est la nature du quadrilatère ABDC ?",r"On applique à C le déplacement de A vers B : 3 carreaux à droite, 1 en haut. D’après la définition de la translation, $\res{ABDC\text{ est un parallélogramme}}$ et $\vect{CD}=\vect{AB}$. Les côtés [AB] et [CD] sont parallèles et de même longueur.","Reproduire le déplacement, puis citer la définition.","A,B,C,D=[point('vect-04',p) for p in 'ABCD']\nassert (D[0]-C[0],D[1]-C[1])==(B[0]-A[0],B[1]-A[1]) and (A[0]+D[0],A[1]+D[1])==(B[0]+C[0],B[1]+C[1])"),
W(5,'Vecteur nul et opposé',r"Simplifier $\vect{AA}$. Donner un autre nom du vecteur $-\vect{MN}$, puis calculer $\vect{MN}+\vect{NM}$.",r"$\res{\vect{AA}=\vec0}$, le vecteur nul. L’opposé de $\vect{MN}$ est $\res{\vect{NM}}$ : même direction, même longueur, sens contraire. Par Chasles, $\vect{MN}+\vect{NM}=\vect{MM}=\res{\vec0}$.","Utiliser les définitions, puis la relation de Chasles.","M,N=point('vect-05','M'),point('vect-05','N'); assert (M[0]-N[0],M[1]-N[1])==(-vecteur('vect-05','M','N')[0],-vecteur('vect-05','M','N')[1])"),
W(6,'Parallélogramme et égalités',r"ABCD est un parallélogramme. Compléter avec des points de la figure : $\vect{AB}=\vect{D\,\ldots}$ ; $\vect{AD}=\vect{\ldots\,C}$ ; $\vect{BA}=\vect{C\,\ldots}$ ; $\vect{CB}=\vect{\ldots\,A}$.",r"Dans ABCD, les côtés opposés donnent $\res{\vect{AB}=\vect{DC}}$ et $\res{\vect{AD}=\vect{BC}}$. En changeant le sens : $\res{\vect{BA}=\vect{CD}}$ et $\res{\vect{CB}=\vect{DA}}$. L’ordre des lettres suit le tour du parallélogramme.","Suivre les côtés opposés dans le même sens.","v=lambda p,q:vecteur('vect-06',p,q)\nassert v('A','B')==v('D','C') and v('A','D')==v('B','C') and v('B','A')==v('C','D') and v('C','B')==v('D','A')"),
W(7,'Démontrer un parallélogramme',r"On sait que $\vect{EF}=\vect{HG}$. Démontrer que EFGH est un parallélogramme, puis vérifier cette égalité sur le quadrillage.",r"D’après la propriété du cours, $\vect{AB}=\vect{CD}$ équivaut à « ABDC est un parallélogramme ». Avec A = E, B = F, C = H et D = G, on obtient que $\res{EFGH\text{ est un parallélogramme}}$. Sur le quadrillage, les deux flèches correspondent au déplacement 4 à droite, 1 en haut.","Remplacer les lettres dans la propriété sans changer leur ordre.","assert vecteur('vect-07','E','F')==vecteur('vect-07','H','G')==(4,1)"),
W(8,'La relation de Chasles',r"Simplifier : $\vect{AB}+\vect{BC}$ ; $\vect{MN}+\vect{NP}+\vect{PQ}$ ; $\vect{AB}+\vect{CA}$ ; $\vect{AB}+\vect{BA}$.",r"$\res{\vect{AB}+\vect{BC}=\vect{AC}}$, comme sur la figure. $\vect{MN}+\vect{NP}+\vect{PQ}=\res{\vect{MQ}}$. En changeant l’ordre des termes, $\vect{CA}+\vect{AB}=\res{\vect{CB}}$. Enfin $\vect{AB}+\vect{BA}=\res{\vec0}$.","Enchaîner les vecteurs bout à bout : l’extrémité de l’un est l’origine du suivant.","v=lambda p,q:vecteur('vect-08',p,q)\nab,bc,ac=v('A','B'),v('B','C'),v('A','C')\nassert (ab[0]+bc[0],ab[1]+bc[1])==ac"),
W(9,'Construire une somme',r"Les vecteurs $\vec u$ et $\vec v$ sont dessinés ; le côté d’un carreau représente 1 cm. Construire un représentant de $\vec u+\vec v$ d’origine O, puis calculer sa longueur.",r"On trace $\vect{OP}=\vec u$ (3 à droite, 1 en haut), puis $\vect{PS}=\vec v$ (1 à droite, 2 en haut). Alors $\vec u+\vec v=\vect{OS}$, soit 4 à droite et 3 en haut : $OS=\sqrt{16+9}=\res{5\text{ cm}}$. Les longueurs de $\vec u$ et $\vec v$, $\sqrt{10}$ et $\sqrt5$, ont une somme différente.","Mettre les représentants bout à bout.","assert vecteur('vect-09','O','P')==(3,1) and vecteur('vect-09','P','S')==(1,2) and vecteur('vect-09','O','S')==(4,3) and sqrt(10)+sqrt(5)!=5"),
W(10,'Deux translations successives',r"On applique au point M la translation de vecteur $\vect{AB}$, ce qui donne M’, puis la translation de vecteur $\vect{BC}$, ce qui donne M’’. Construire M’ et M’’. Par quelle translation unique passe-t-on de M à M’’ ?",r"$\vect{MM'}=\vect{AB}$ et $\vect{M'M''}=\vect{BC}$. Par Chasles, $\vect{MM''}=\vect{MM'}+\vect{M'M''}=\vect{AB}+\vect{BC}=\vect{AC}$ : c’est la $\res{\text{translation de vecteur }\vect{AC}}$. On le vérifie sur le quadrillage : 4 à droite, 3 en haut.","Remplacer chaque déplacement par un vecteur, puis additionner.","v=lambda p,q:vecteur('vect-10',p,q)\nassert v('M',\"M'\")==v('A','B') and v(\"M'\",\"M''\")==v('B','C') and v('M',\"M''\")==v('A','C')"),
W(11,'La règle du parallélogramme',r"ABCD est un parallélogramme. Démontrer que $\vect{AB}+\vect{AD}=\vect{AC}$.",r"ABCD est un parallélogramme, donc $\vect{AD}=\vect{BC}$. Ainsi $\vect{AB}+\vect{AD}=\vect{AB}+\vect{BC}$, et la relation de Chasles donne $\res{\vect{AB}+\vect{AD}=\vect{AC}}$. La diagonale issue de A représente la somme.","Remplacer un vecteur par un vecteur égal, puis appliquer Chasles.","v=lambda p,q:vecteur('vect-11',p,q)\nassert v('A','D')==v('B','C') and (v('A','B')[0]+v('A','D')[0],v('A','B')[1]+v('A','D')[1])==v('A','C')"),
W(12,'Milieu et vecteurs',r"I est le milieu de [AB]. Démontrer que $\vect{AI}=\vect{IB}$ et que $\vect{AB}=2\vect{AI}$. Réciproquement, si un point J vérifie $\vect{AJ}=\vect{JB}$, que peut-on dire de J ?",r"I est sur [AB] à égale distance de A et B : $\vect{AI}$ et $\vect{IB}$ ont même direction, même sens et même longueur, donc $\res{\vect{AI}=\vect{IB}}$. Par Chasles, $\vect{AB}=\vect{AI}+\vect{IB}=\vect{AI}+\vect{AI}=\res{2\vect{AI}}$. Si $\vect{AJ}=\vect{JB}$, alors AJBJ est un parallélogramme aplati : ses diagonales [AB] et [JJ] ont même milieu, donc $\res{J\text{ est le milieu de }[AB]}$.","Traduire « milieu » en direction, sens et longueur.","assert vecteur('vect-12','A','I')==vecteur('vect-12','I','B') and 2*vecteur('vect-12','A','I')[0]==vecteur('vect-12','A','B')[0]"),
W(13,'Un drone',r"Un drone part de D, se déplace de 60 m vers l’est, puis de 80 m vers le nord. Représenter les deux déplacements par des vecteurs sur le quadrillage, où un carreau représente 20 m. Quel déplacement unique produit le même effet ? Quelle distance sépare le point d’arrivée F du point de départ ?",r"Le premier déplacement est $\vect{DE}$, le second $\vect{EF}$. Par Chasles, leur somme est $\res{\vect{DF}}$. Le triangle DEF est rectangle en E : $DF=\sqrt{60^2+80^2}=\res{100\text{ m}}$, alors que le drone a parcouru 140 m.","Additionner les déplacements, puis calculer la longueur avec Pythagore.","assert vecteur('vect-13','D','F')==(3,4) and 60**2+80**2==100**2"),
W(14,'Une frise',r"Une frise est obtenue en répétant un motif par la translation de vecteur $\vec u$, de longueur 4 cm. Quelle translation transforme le motif 1 en motif 6 ? Le motif 6 en motif 2 ? Donner les longueurs des vecteurs correspondants.",r"Du motif 1 au motif 6, il y a cinq déplacements : $\vec u+\vec u+\vec u+\vec u+\vec u$, noté $5\vec u$, de longueur $\res{20\text{ cm}}$. Du motif 6 au motif 2, on revient de quatre motifs : $\res{-4\vec u}$, même direction, sens contraire, longueur $\res{16\text{ cm}}$.","Compter les intervalles entre les motifs.","assert (6-1)*4==20 and (6-2)*4==16",fig='vect-frise'),
W(15,'Démontrer avec des vecteurs',r"ABCD est un parallélogramme et E est le point tel que $\vect{BE}=\vect{AB}$. Démontrer que DCEB est un parallélogramme.",r"ABCD est un parallélogramme, donc $\vect{DC}=\vect{AB}$. Par hypothèse $\vect{BE}=\vect{AB}$. Donc $\vect{DC}=\vect{BE}$, ce qui signifie que $\res{DCEB\text{ est un parallélogramme}}$, d’après la propriété du cours appliquée aux points D, C, B, E.","Chaîner deux égalités de vecteurs, puis citer la propriété.","v=lambda p,q:vecteur('vect-15',p,q)\nassert v('D','C')==v('A','B')==v('B','E')")
],reperes=['Symétrie, demi-tour et translation','Vecteurs égaux, nul et opposé','Parallélogramme et égalité de vecteurs','Somme de vecteurs et relation de Chasles'],deco='vecteursplan')

def V(i,t,e,c,m,k,fig=None):
    return E(t,e,c,m,k,figure=fig or f'espace-{i:02}')

chapitre(16,'espace','Espace : sphère, boule et sections','4 · Espace et géométrie',
'Solides · Volumes · Sphère et boule · Grands cercles · Sections planes',
['Reconnaître les solides et calculer leurs volumes.','Définir la sphère, la boule et leurs grands cercles.','Visualiser et calculer des sections planes.'],['Aires usuelles, Pythagore, Thalès et unités de volume.'],[
r'''\essSection{1}{Solides, sphère et boule}
\begin{propriete}Pour un pavé : $V=L\ell h$. Pour un prisme droit ou un cylindre : $V=\mathcal A_{\rm base}\times h$. Pour une pyramide ou un cône : $V=\mathcal A_{\rm base}\times h/3$. La hauteur est perpendiculaire à la base.\end{propriete}
\begin{definition}La sphère de centre O et de rayon R est l’ensemble des points de l’espace situés à la distance R de O. La boule de centre O et de rayon R est l’ensemble des points situés à une distance de O inférieure ou égale à R.\end{definition}
\begin{definition}Un grand cercle de la sphère est un cercle de centre O et de rayon R tracé sur la sphère. Deux points A et B de la sphère sont diamétralement opposés lorsque O est le milieu de [AB] ; alors $AB=2R$ et [AB] est un diamètre.\end{definition}
\begin{propriete}Le volume d’une boule de rayon $r$ est $V=\dfrac43\pi r^3$. Cette formule est admise.\end{propriete}
\begin{savoirfaire}[Assembler]Décomposer en solides usuels, additionner des volumes sans recouvrement ou soustraire un creux. Conserver $\pi$ jusqu’au résultat final, puis convertir : $1\text{ dm}^3=1\text{ L}$.\end{savoirfaire}''',
r'''\essSection{2}{Sections planes}
\begin{propriete}La section d’un pavé par un plan parallèle à une face est un rectangle de mêmes dimensions que cette face ; par un plan parallèle à une arête, c’est un rectangle.\end{propriete}
\begin{propriete}La section d’un cylindre par un plan perpendiculaire à son axe est un disque de même rayon que la base ; par un plan parallèle à son axe, c’est un rectangle.\end{propriete}
\begin{propriete}La section d’une pyramide ou d’un cône par un plan parallèle à la base est une réduction de la base : même nature, dimensions proportionnelles. Le coefficient est le quotient de la distance au sommet par la hauteur.\end{propriete}
\begin{propriete}La section d’une boule par un plan est un disque. Si le plan est à la distance $d$ du centre, avec $d<R$, le rayon $r$ du disque vérifie $r^2=R^2-d^2$ d’après Pythagore. Le plan passant par le centre donne un grand cercle.\end{propriete}
\begin{savoirfaire}[Dessiner en vraie grandeur]Reporter les longueurs utiles à partir de la face avant de la perspective, ou les calculer, puis tracer la section à part, sans déformation.\end{savoirfaire}'''],[
V(1,'Un pavé',r"Un pavé a pour dimensions 8 cm, 5 cm et 3 cm. Calculer son volume en cm$^3$ puis en litres.",r"$V=8\times5\times3=\res{120\text{ cm}^3}$. Comme $1\text{ L}=1000\text{ cm}^3$, cela fait $\res{0{,}12\text{ L}}$.","Multiplier les trois dimensions, puis convertir.","assert 8*5*3==120 and Rational(120,1000)==Rational('0.12')"),
V(2,'Un cylindre',r"Un cylindre a un rayon de 3 cm et une hauteur de 10 cm. Donner son volume exact et au cm$^3$.",r"$V=\pi\times3^2\times10=\res{90\pi\text{ cm}^3}\approx\res{283\text{ cm}^3}$. Le rayon est déjà fourni, il ne faut pas le diviser par deux.","Calculer l’aire du disque de base.","assert 3**2*10==90 and round(90*math.pi)==283"),
V(3,'Une pyramide',r"Une pyramide a une base carrée de côté 6 cm et une hauteur de 9 cm. Calculer son volume. Quelle est la nature de sa base ?",r"La base est un carré d’aire 36 cm$^2$. Le volume vaut $36\times9/3=\res{108\text{ cm}^3}$. La division par trois distingue la pyramide du prisme de même base et de même hauteur.","Utiliser la hauteur perpendiculaire à la base.","assert 6**2*9/3==108"),
V(4,'Un cône',r"Un cône a pour diamètre 8 cm et hauteur 9 cm. Calculer son volume exact.",r"Le rayon est 4 cm. $V=\pi\times4^2\times9/3=\res{48\pi\text{ cm}^3}$. Employer 8 comme rayon multiplierait le résultat par quatre.","Passer du diamètre au rayon.","assert 4**2*9/3==48"),
V(5,'Une boule',r"Une boule a un rayon de 3 cm. Donner son volume exact puis arrondi au cm$^3$. Quelle est la longueur d’un grand cercle de sa sphère ?",r"$V=\dfrac43\pi\times27=\res{36\pi\text{ cm}^3}\approx\res{113\text{ cm}^3}$. Un grand cercle a pour rayon 3 cm : sa longueur vaut $2\pi\times3=\res{6\pi\text{ cm}}$, environ 18,8 cm.",r"Élever le rayon au cube, puis multiplier par $4\pi/3$.","assert Rational(4,3)*3**3==36 and round(36*math.pi)==113"),
E('Sphère, boule et grands cercles',r"La sphère de centre O a pour rayon 4 cm. A et B sont diamétralement opposés, C est sur la sphère, OM = 2 cm et ON = 6 cm. Quels points appartiennent à la sphère ? À la boule ? Calculer AB et la longueur du grand cercle passant par A et B.",r"A, B et C sont à 4 cm de O : ils appartiennent à la $\res{\text{sphère}}$, donc aussi à la boule. M est à 2 cm de O : il est $\res{\text{dans la boule, pas sur la sphère}}$. N est à 6 cm : $\res{\text{à l’extérieur}}$. [AB] est un diamètre : $\res{AB=8\text{ cm}}$. Le grand cercle passant par A et B a pour longueur $\res{8\pi\text{ cm}}$.","Comparer chaque distance au centre avec le rayon.","assert 2*4==8 and 2<4<6",figure='espace-sphere-vocab'),
E('Une pyramide dans un cube',r"ABCDEFGH est un cube d’arête 6 cm ; E est le sommet situé au-dessus de A. On considère la pyramide EABCD de sommet E et de base ABCD. Donner la nature de ses cinq faces, puis son volume. Quelle fraction du cube représente-t-elle ?",r"La base ABCD est un carré. EAB et EAD sont des triangles $\res{\text{rectangles isocèles en A}}$, moitiés de faces du cube. La droite (BC) est perpendiculaire à la face ABFE, donc à (BE) : EBC est $\res{\text{rectangle en B}}$ ; de même EDC est rectangle en D. Le volume vaut $36\times6/3=\res{72\text{ cm}^3}$, soit $\res{1/3}$ du cube de $216\text{ cm}^3$.","Repérer la base, la hauteur [EA] et les angles droits des faces.","assert 6**2*6/3==72 and Rational(72,216)==Rational(1,3)",figure='espace-pyramide-cube'),
V(8,'Une section de pavé',r"Un pavé de base 8 cm sur 5 cm et de hauteur 6 cm est coupé par un plan parallèle à la base à 2 cm de celle-ci. Quelle forme et quelle aire a la section ?",r"La section est un $\res{\text{rectangle de 8 cm sur 5 cm}}$, comme la base. Son aire vaut $\res{40\text{ cm}^2}$. La hauteur de coupe ne modifie pas cette section parallèle dans un pavé.","Reconnaître une section parallèle à une face.","assert 8*5==40",fig='espace-section-pave'),
E('Sections d’un cylindre',r"Un cylindre a un rayon de 3 cm et une hauteur de 10 cm. Décrire et calculer l’aire de sa section par un plan perpendiculaire à son axe, puis par un plan contenant son axe.",r"Perpendiculairement à l’axe, la section est un $\res{\text{disque de rayon 3 cm}}$, d’aire $\res{9\pi\text{ cm}^2}$. Un plan contenant l’axe donne un $\res{\text{rectangle de 6 cm sur 10 cm}}$ : sa largeur est un diamètre de la base. Son aire vaut $\res{60\text{ cm}^2}$.","Identifier la direction du plan par rapport à l’axe.","assert 3**2==9 and 2*3*10==60",figure='espace-section-cylindre'),
V(13,'Une section de sphère',r"Une sphère de centre O a un rayon de 5 cm. Un plan la coupe à une distance OH = 3 cm du centre ; H est le centre du cercle de section. Calculer le rayon de ce cercle et l’aire du disque de section.",r"Pour M sur le cercle, OHM est rectangle en H. $HM^2=OM^2-OH^2=25-9=16$, donc $\res{HM=4\text{ cm}}$. Le disque a pour aire $\res{16\pi\text{ cm}^2}$.","Passer par le triangle rectangle de la section.","assert 5**2-3**2==4**2",fig='espace-section-sphere'),
V(11,'Un réservoir assemblé',r"Un réservoir fermé est formé d’un cylindre de rayon 1 m et de hauteur 2 m, surmonté d’une demi-boule de même rayon. Calculer sa capacité au litre.",r"Le cylindre vaut $2\pi$ m$^3$, la demi-boule $\frac12\times\frac43\pi=\frac{2\pi}3$ m$^3$. Le total est $8\pi/3$ m$^3$, soit $8000\pi/3$ L, environ $\res{8378\text{ L}}$. Les deux parties ne se recouvrent qu’à leur frontière.","Additionner les volumes puis convertir.","assert round(8000*math.pi/3)==8378",fig='espace-reservoir'),
V(12,'Une boule creusée',r"Une boule pleine de rayon 5 cm contient une cavité sphérique de rayon 2 cm, entièrement intérieure. Quel volume de matière reste-t-il ?",r"On soustrait les volumes : $V=\frac43\pi(5^3-2^3)=\frac43\pi\times117=\res{156\pi\text{ cm}^3}$. Il faut soustraire des cubes, pas calculer le volume d’une boule de rayon $5-2$.","Soustraire les volumes du plein et du creux.","assert Rational(4,3)*(5**3-2**3)==156",fig='espace-cavite'),
V(14,'Un cône coupé',r"Un cône de rayon 6 cm et de hauteur 12 cm est coupé par un plan parallèle à sa base, à mi-hauteur. Quelle est la section ? Calculer le volume du petit cône de même sommet, puis celui du tronc restant.",r"La section est une réduction de la base de coefficient $6/12=1/2$ : un $\res{\text{disque de rayon 3 cm}}$. Le petit cône a pour rayon 3 cm et hauteur 6 cm : $V=\pi\times9\times6/3=\res{18\pi\text{ cm}^3}$. Le grand cône vaut $\pi\times36\times12/3=144\pi$ cm$^3$ ; le tronc vaut $\res{126\pi\text{ cm}^3}$.","Utiliser les dimensions proportionnelles de la section, puis soustraire.","assert 3**2*6/3==18 and 6**2*12/3==144 and 144-18==126",fig='espace-cone-coupe'),
E('Une section de pyramide',r"SABCD est une pyramide de base carrée ABCD de côté 6 cm et de hauteur SO = 9 cm. Un plan parallèle à la base coupe la pyramide à 3 cm du sommet S. Déterminer la nature et l’aire de la section, puis le volume de la petite pyramide obtenue.",r"La section est une réduction de la base de coefficient $3/9=1/3$ : un $\res{\text{carré de côté 2 cm}}$, d’aire $\res{4\text{ cm}^2}$. La petite pyramide a pour hauteur 3 cm : $V=4\times3/3=\res{4\text{ cm}^3}$.","Calculer le coefficient de réduction à partir des hauteurs.","assert 6*Rational(3,9)==2 and 2**2*3/3==4",figure='espace-section-pyramide'),
E('Le cylindre d’Archimède',r"Une boule de rayon 3 cm est posée dans un cylindre de rayon 3 cm et de hauteur 6 cm, qu’elle touche en haut, en bas et sur le côté. Calculer les deux volumes et le rapport du volume de la boule à celui du cylindre. Montrer que ce rapport ne dépend pas du rayon.",r"Le cylindre vaut $\pi\times9\times6=54\pi$ cm$^3$ et la boule $36\pi$ cm$^3$. Le rapport vaut $36/54=\res{2/3}$. Pour un rayon $r$ : le cylindre vaut $\pi r^2\times2r=2\pi r^3$ et la boule $\frac43\pi r^3$, d’où $\res{\frac{4/3}{2}=\frac23}$ pour tout $r$. Archimède avait découvert ce résultat.","Écrire les deux volumes avec le même rayon, puis simplifier.","r=symbols('r',positive=True); assert simplify(Rational(4,3)*pi*r**3/(pi*r**2*2*r))==Rational(2,3) and Rational(36,54)==Rational(2,3)",figure='espace-archimede')
],reperes=['Volumes usuels et boule','Sphère, boule et grands cercles','Sections planes de solides','Assemblages et problèmes de volumes'],deco='espace')
